// =====================================================================
// MATCHING LOGIC — adapt this for your own test case / log structure
// =====================================================================
//
// For each test case row from the test sheet, find the matching row in
// the interaction log sheet (the AI's actual response to that test).
//
// To adapt this workflow for a different setup, change:
//   - getCol(...) column-name fallbacks     → match your test sheet headers
//   - extractTestId() regex patterns         → match your test-ID format
//   - The 4 matching passes                  → keep, drop, reorder, or
//                                              swap in your own heuristic
//                                              (embeddings, edit distance,
//                                              custom hash, foreign key…)
//   - The similarity threshold (default 0.25)→ tune for your data noise
//
// Output per item: { TEST_ID, testCase: <raw test row>, log: <raw log row | null> }
// Downstream nodes derive sheet-ready fields from this shape.

const testCases = $('Read Test Cases').all().map(i => i.json);
const logs = $input.all().map(i => i.json);

if (testCases.length === 0) throw new Error('No test cases found.');
if (logs.length === 0) throw new Error('No interaction logs found.');

// ---- Helpers ----
const getCol = (obj, ...names) => {
  for (const n of names) {
    if (obj[n] !== undefined && obj[n] !== null && obj[n] !== '') return obj[n];
  }
  return '';
};

const decodeHtml = s => String(s || '')
  .replace(/&#0*39;/g, "'").replace(/&apos;/g, "'")
  .replace(/&quot;/g, '"').replace(/&#0*34;/g, '"')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&nbsp;/g, ' ').replace(/\\#/g, '#');

const normalize = t => decodeHtml(t).toLowerCase()
  .replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

const tokenSet = (t, minLen = 3) =>
  new Set(normalize(t).split(' ').filter(w => w.length >= minLen));

const dice = (a, b) => {
  if (!a.size || !b.size) return 0;
  let inter = 0;
  for (const v of a) if (b.has(v)) inter++;
  return (2 * inter) / (a.size + b.size);
};

const overlap = (a, b) => {
  if (!a.size || !b.size) return 0;
  let inter = 0;
  for (const v of a) if (b.has(v)) inter++;
  return inter / Math.min(a.size, b.size);
};

// CUSTOMIZE: how is a test ID embedded in the log's query field?
// Current: recognizes 'TC123' and 'CAT1-A-001' plus a subject="…" wrapper.
const extractTestId = text => {
  if (!text) return null;
  const s = String(text);
  const c1 = s.match(/subject\s*=\s*"\s*(CAT\d+-[A-Z]-\d+)/i); if (c1) return c1[1].toUpperCase();
  const c2 = s.match(/\bCAT\d+-[A-Z]-\d+\b/i);                  if (c2) return c2[0].toUpperCase();
  const m1 = s.match(/subject\s*=\s*"\s*(TC\d+)/i);             if (m1) return m1[1].toUpperCase();
  const m2 = s.match(/\bTC(\d+)\b/i);                           if (m2) return ('TC' + m2[1]).toUpperCase();
  return null;
};

// ---- Prepare comparable shapes ----
const tcs = testCases.map(tc => {
  const id = String(getCol(tc, 'TEST_ID', 'TEST ID', 'Test ID')).trim().toUpperCase();
  const subject = getCol(tc, 'TICKET_SUBJECT', 'TICKET SUBJECT', 'SUBJECT');
  const body = getCol(tc, 'CUSTOMER_QUESTION', 'CUSTOMER QUESTION', 'QUESTION',
                          'EMAIL_BODY_FOR_AI', 'EMAIL BODY FOR AI', 'EMAIL_BODY', 'EMAIL BODY');
  const combined = (subject || '') + ' ' + (body || '');
  return { id, raw: tc, normBody: normalize(body), set: tokenSet(combined) };
});

const logInfos = logs.map(l => ({
  raw: l,
  normQ: normalize(String(l.query || '')),
  tcId: extractTestId(String(l.query || '')),
  set: tokenSet(String(l.query || ''))
}));

// ---- Match each test case to a log (4-pass strategy) ----
const tcToLog = new Map();
const used = new Set();
const tcIds = new Set(tcs.map(t => t.id));

// Pass 1: explicit test-ID match (log query contains the test ID)
for (const li of logInfos) {
  if (li.tcId && tcIds.has(li.tcId) && !tcToLog.has(li.tcId)) {
    tcToLog.set(li.tcId, li); used.add(li);
  }
}

// Pass 2: exact normalized body match
for (const tc of tcs) {
  if (tcToLog.has(tc.id) || !tc.normBody) continue;
  for (const li of logInfos) {
    if (used.has(li) || li.tcId) continue;
    if (li.normQ === tc.normBody) { tcToLog.set(tc.id, li); used.add(li); break; }
  }
}

// Pass 3: substring containment (for sufficiently long bodies)
for (const tc of tcs) {
  if (tcToLog.has(tc.id) || !tc.normBody || tc.normBody.length < 60) continue;
  let best = null, bestLen = 0;
  for (const li of logInfos) {
    if (used.has(li) || li.tcId || !li.normQ) continue;
    if (li.normQ.includes(tc.normBody) || tc.normBody.includes(li.normQ)) {
      const len = Math.min(li.normQ.length, tc.normBody.length);
      if (len > bestLen) { bestLen = len; best = li; }
    }
  }
  if (best) { tcToLog.set(tc.id, best); used.add(best); }
}

// Pass 4: token-set similarity fallback (Dice or Overlap >= 0.25)
for (const tc of tcs) {
  if (tcToLog.has(tc.id) || !tc.set.size) continue;
  let best = null, bestScore = 0;
  for (const li of logInfos) {
    if (used.has(li) || li.tcId || !li.set.size) continue;
    const score = Math.max(dice(tc.set, li.set), overlap(tc.set, li.set) * 0.9);
    if (score > bestScore) { bestScore = score; best = li; }
  }
  if (best && bestScore >= 0.25) { tcToLog.set(tc.id, best); used.add(best); }
}

// ---- Output: one item per test case with its matched log attached ----
return tcs.map(tc => {
  const li = tcToLog.get(tc.id);
  return { json: { TEST_ID: tc.id, testCase: tc.raw, log: li ? li.raw : null } };
}).sort((a, b) =>
  (a.json.TEST_ID || '').localeCompare(b.json.TEST_ID || '', undefined, { numeric: true })
);

// Standard output formatter — derives sheet-ready fields from each
// { TEST_ID, testCase, log } pair produced by the matching node above.
// Edit this if your results sheet uses different columns or you want to
// surface additional log fields.

const NONE_VALS = new Set(['None', 'none', 'N/A', 'n/a', 'null', 'undefined', '']);
const cleanNone = v => {
  if (v === undefined || v === null || v === false) return '';
  const s = String(v).trim();
  return NONE_VALS.has(s) ? '' : s;
};
const num = v => {
  if (v === '' || v === null || v === undefined) return null;
  const n = parseFloat(String(v).replace(',', '.'));
  return isNaN(n) ? null : n;
};
const toBool = v => {
  if (v === true) return true;
  if (v === false) return false;
  const s = String(v == null ? '' : v).trim().toLowerCase();
  return s === 'true' || s === 'yes' || s === '1';
};

return $input.all().map(item => {
  const { TEST_ID, testCase, log } = item.json;

  if (!log) {
    return { json: {
      TEST_ID,
      TIMESTAMP: '',
      ACTUAL_CLASSIFICATION: '',
      ACTUAL_ESCALATION: '',
      CLASSIFICATION_CORRECT: '',
      AI_RESPONSE: '',
      RESPONSE_TIME_MS: '',
      CONFIDENCE_SCORE: ''
    }};
  }

  const aiResponse = cleanNone(log.response);
  const timestamp = cleanNone(log.timestampReceived) || cleanNone(log.timestampStart) || cleanNone(log.timestampEnd);
  const tStart = cleanNone(log.timestampStart) || cleanNone(log.timestampReceived);
  const tEnd = cleanNone(log.timestampEnd);

  let aiMs = '';
  if (tStart && tEnd) {
    const ms = new Date(tEnd).getTime() - new Date(tStart).getTime();
    if (!isNaN(ms) && ms >= 0) aiMs = ms;
  }
  if (aiMs === '') {
    const sec = num(log.responseTime);
    if (sec !== null) aiMs = Math.round(sec * 1000);
  }

  const isEscalated = toBool(cleanNone(log.isEscalated));
  const actualClassification = isEscalated ? 'HUMAN_REQUIRED' : 'AI_HANDLES';
  const actualEscalation = isEscalated ? 'YES' : 'NO';

  const expected = String(
    testCase.EXPECTED_CLASSIFICATION ||
    testCase['EXPECTED CLASSIFICATION'] ||
    ''
  ).trim().toUpperCase();
  const classificationCorrect = expected
    ? (expected === actualClassification ? 'TRUE' : 'FALSE')
    : '';

  return { json: {
    TEST_ID,
    TIMESTAMP: timestamp,
    ACTUAL_CLASSIFICATION: actualClassification,
    ACTUAL_ESCALATION: actualEscalation,
    CLASSIFICATION_CORRECT: classificationCorrect,
    AI_RESPONSE: aiResponse,
    RESPONSE_TIME_MS: aiMs,
    CONFIDENCE_SCORE: cleanNone(log.confidenceScore)
  }};
});
